const headers = $input.first().json.headers || {};
const token   = headers['x-internal-token'] || headers['X-Internal-Token'];

if (!token || token !== $env.INTERNAL_WEBHOOK_SECRET) {
  throw new Error('UNAUTHORIZED_REQUEST: invalid or missing token');
}

return [{ json: $input.first().json }];

const items = $items('Load Lead');

if (!items || items.length === 0) {
  throw new Error('LEAD_NOT_FOUND: no lead matched the provided lead_id');
}

const lead = items[0].json;
if (!lead || !lead.id) {
  throw new Error('LEAD_NOT_FOUND: lead record is empty');
}

// ── Fix: strip protocol before building Jina URL ──────────────────
// Prevents: https://r.jina.ai/https://company.com
const raw = lead.website || `https://${lead.email_domain}`;
const scrapeTarget = raw.replace(/^https?:\/\//, '');

return [{
  json: {
    ...lead,
    scrape_target: scrapeTarget   // protocol-free, e.g. "acme.com"
  }
}];

// ── Merge all enrichment API results ──────────────────────────────
// Each branch may have succeeded or failed independently.
// Partial failure is acceptable — we log gaps and continue.

const lead = $items('Validate Lead Loaded')[0].json;

// ── Clearbit ──────────────────────────────────────────────────────
let clearbit = {};
try {
  const cb = $items('Clearbit Enrichment')[0].json;
  clearbit = {
    bio:              cb?.person?.bio             || null,
    location:         cb?.person?.location        || null,
    twitter:          cb?.person?.twitter?.handle || null,
    seniority:        cb?.person?.employment?.seniority || null,
    employment_role:  cb?.person?.employment?.role || null,
    company_domain:   cb?.company?.domain         || null,
    company_type:     cb?.company?.type           || null,
    company_size:     cb?.company?.metrics?.employees    || null,
    company_revenue:  cb?.company?.metrics?.annualRevenue || null,
    industry:         cb?.company?.category?.industry    || null,
    sub_industry:     cb?.company?.category?.subIndustry || null,
    company_country:  cb?.company?.geo?.country   || null,
    company_city:     cb?.company?.geo?.city      || null,
    technologies:     cb?.company?.tech           || [],
    funding_raised:   cb?.company?.metrics?.raised || null,
    alexa_rank:       cb?.company?.metrics?.alexaGlobalRank || null
  };
} catch(e) { clearbit = { error: 'clearbit_unavailable' }; }

// ── Apollo ────────────────────────────────────────────────────────
let apollo = {};
try {
  const ap = $items('Apollo Enrichment')[0].json?.person || {};
  apollo = {
    apollo_id:        ap.id                          || null,
    headline:         ap.headline                    || null,
    seniority:        ap.seniority                   || null,
    departments:      ap.departments                 || [],
    intent_strength:  ap.intent_strength             || null,
    company_linkedin: ap.organization?.linkedin_url  || null,
    company_founded:  ap.organization?.founded_year  || null,
    keywords:         ap.organization?.keywords      || []
  };
} catch(e) { apollo = { error: 'apollo_unavailable' }; }

// ── Jina Website Content ──────────────────────────────────────────
let jina = {};
try {
  const ji = $items('Jina Website Scrape')[0].json;
  const content = ji?.data?.content || ji?.content || '';
  jina = {
    website_title:   ji?.data?.title || null,
    website_content: content.slice(0, 8000),   // raw cap — compressed below
    scraped_url:     ji?.data?.url  || null
  };
} catch(e) { jina = { error: 'jina_unavailable' }; }

// ── BuiltWith Tech Stack ──────────────────────────────────────────
let builtwith = {};
try {
  const bw    = $items('BuiltWith Tech Stack')[0].json;
  const paths = bw?.Results?.[0]?.Result?.Paths || [];
  const techNames = [];
  paths.forEach(p => {
    (p.Technologies || []).forEach(t => { if (t.Name) techNames.push(t.Name); });
  });
  builtwith = {
    technologies: [...new Set(techNames)],
    tech_count:   techNames.length
  };
} catch(e) { builtwith = { error: 'builtwith_unavailable' }; }

// ── Unified tech stack — deduplicated and CAPPED at 50 ────────────
// BuiltWith can return hundreds of entries; large arrays bloat DB rows
const allTech = [
  ...(Array.isArray(clearbit.technologies) ? clearbit.technologies : []),
  ...(Array.isArray(builtwith.technologies) ? builtwith.technologies : [])
];
const techStack = [...new Set(
  allTech.map(t => typeof t === 'string' ? t : (t.name || t.tag || JSON.stringify(t)))
)].slice(0, 50);   // hard cap

return [{
  json: {
    lead_id:      lead.id,
    email:        lead.email,
    email_domain: lead.email_domain,
    clearbit,
    apollo,
    jina,
    builtwith,
    tech_stack:   techStack,
    enriched_at:  new Date().toISOString(),
    execution_id: $execution.id
  }
}];

// ── Token compression before OpenAI ───────────────────────────────
// Reduces prompt size by ~40% — key for cost control at scale.
//
// Strategy:
//   1. Collapse whitespace in website content
//   2. Trim to 1200 chars (vs 2000 raw)
//   3. Cap tech stack to 15 items for prompt (full 50 still in DB)
//   4. Cap Apollo keywords to 10

const d = $input.first().json;

const rawContent = d.jina?.website_content || '';
const websiteSummary = rawContent
  .replace(/<[^>]*>/g, '')        // strip any residual HTML tags
  .replace(/\s+/g, ' ')           // collapse whitespace
  .replace(/https?:\/\/\S+/g, '') // strip URLs
  .trim()
  .slice(0, 1200);

const techForPrompt   = (d.tech_stack   || []).slice(0, 15);
const keywordsForPrompt = (d.apollo?.keywords || []).slice(0, 10);

return [{
  json: {
    ...d,
    website_summary:    websiteSummary,
    tech_for_prompt:    techForPrompt,
    keywords_for_prompt: keywordsForPrompt
  }
}];

// ── Cache Hit Path ─────────────────────────────────────────────────
// Company was enriched within the last 7 days.
// Re-use cached company data and skip all API calls.
// We still need to generate a Lead Brief if one doesn't exist.

const lead    = $items('Validate Lead Loaded')[0].json;
const company = $items('Check Company Cache')[0].json;

const techStack = Array.isArray(company.tech_stack)
  ? company.tech_stack
  : (typeof company.tech_stack === 'string'
      ? JSON.parse(company.tech_stack)
      : []);

return [{
  json: {
    lead_id:      lead.id,
    email:        lead.email,
    email_domain: lead.email_domain,
    clearbit: {
      industry:        company.industry,
      sub_industry:    company.sub_industry,
      company_size:    company.employee_count,
      company_revenue: company.annual_revenue,
      company_country: company.country,
      company_city:    company.city,
      company_type:    company.company_type,
      funding_raised:  company.funding_raised,
      alexa_rank:      company.alexa_rank
    },
    apollo: {
      company_linkedin: company.linkedin_url,
      company_founded:  company.founded_year,
      keywords: []
    },
    jina:       { website_content: '', website_title: null },
    builtwith:  { technologies: techStack },
    tech_stack: techStack.slice(0, 50),
    from_cache: true,
    enriched_at: new Date().toISOString(),
    execution_id: $execution.id
  }
}];

// Same compression step for cache-hit path
const d = $input.first().json;

return [{
  json: {
    ...d,
    website_summary:     '',
    tech_for_prompt:     (d.tech_stack || []).slice(0, 15),
    keywords_for_prompt: []
  }
}];

