{
  "lead_summary": "2-3 sentence summary of who this person is",
  "company_summary": "2-3 sentence summary of the company",
  "icp_signals": ["signals suggesting ICP fit"],
  "pain_points": ["likely pain points based on role, industry, tech stack"],
  "conversation_hooks": ["2-3 specific personalised talking points"],
  "recommended_approach": "brief outreach strategy recommendation",
  "risk_flags": ["anything suggesting poor fit or risk"]
}

Lead:
Name: ${$items('Validate Lead Loaded')[0].json.full_name}
Title: ${$items('Validate Lead Loaded')[0].json.title || $json.clearbit?.employment_role || 'Unknown'}
Company: ${$items('Validate Lead Loaded')[0].json.company || $json.email_domain}
Industry: ${$json.clearbit?.industry || 'Unknown'}
Size: ${$json.clearbit?.company_size || 'Unknown'} employees
Revenue: ${$json.clearbit?.company_revenue || 'Unknown'}
Location: ${[$json.clearbit?.company_city, $json.clearbit?.company_country].filter(Boolean).join(', ') || 'Unknown'}
Seniority: ${$json.clearbit?.seniority || $json.apollo?.seniority || 'Unknown'}
Tech Stack: ${($json.tech_for_prompt || []).join(', ') || 'Unknown'}
Website: ${$json.website_summary || 'No website data'}
Keywords: ${($json.keywords_for_prompt || []).join(', ') || 'None'}
Funding: ${$json.clearbit?.funding_raised || 'Unknown'}` }}

