const raw = $input.first().json?.choices?.[0]?.message?.content
         || $input.first().json?.message?.content
         || '';

let brief = {};
try {
  const cleaned = raw.replace(/```json|```/g, '').trim();
  brief = JSON.parse(cleaned);
} catch(e) {
  brief = {
    lead_summary:         raw.slice(0, 500),
    company_summary:      null,
    icp_signals:          [],
    pain_points:          [],
    conversation_hooks:   [],
    recommended_approach: null,
    risk_flags:           [],
    parse_error:          e.message
  };
}

// Pull lead_id from whichever enrichment path ran
const leadId = $items('Merge Enrichment Results')?.[0]?.json?.lead_id
            || $items('Build Cached Enrichment')?.[0]?.json?.lead_id;

const enrichedAt = $items('Merge Enrichment Results')?.[0]?.json?.enriched_at
                || $items('Build Cached Enrichment')?.[0]?.json?.enriched_at;

return [{
  json: {
    lead_id:      leadId,
    brief,
    enriched_at:  enrichedAt,
    execution_id: $execution.id
  }
}];

