const err = $input.first().error || {};
const msg = err.message || 'Unknown error in WF-02';

const isAuth     = msg.includes('UNAUTHORIZED_REQUEST');
const isNotFound = msg.includes('LEAD_NOT_FOUND');

return [{
  json: {
    status:       isAuth ? 'unauthorized' : isNotFound ? 'not_found' : 'error',
    message:      msg,
    workflow:     'WF-02',
    timestamp:    new Date().toISOString(),
    execution_id: $execution.id
  }
}];
